+/** The supported language an Accept-Language header prefers most, or `fallback`. */
+export function pickLanguage(header, fallback) {
+  const wanted = [];
+  for (const part of String(header ?? "").split(",")) {
+    const [range, ...attrs] = part.split(";").map((s) => s.replace(/\s/g, "").toLowerCase());
+    const lang = range.split("-")[0];
+    if (!LANGUAGES.includes(lang)) continue;
+    const q = attrs.find((a) => a.startsWith("q="))?.slice(2) ?? "1";
+    if (/^(0(\.\d*)?|1(\.0*)?)$/.test(q) && Number(q) > 0) wanted.push({ lang, q: Number(q) });
+  }
+  return wanted.sort((a, b) => b.q - a.q)[0]?.lang ?? fallback;
 }

